changeSet.sql:
UPDATE topics SET title = replace(title, '&#039;', '''') WHERE title LIKE '%&#039;%';
UPDATE comments SET title = replace(title, '&#039;', '''') WHERE title LIKE '%&#039;%';
UPDATE edit_info SET oldtitle = replace(replace(replace(replace(replace(replace(replace(oldtitle, '&quot;', '"'), '&#171;', '«'), '&#187;', '»'), '&#8222;', '„'), '&#8220;', '“'), '&#8221;', '”'), '&#039;', '''') WHERE oldtitle IS NOT NULL AND oldtitle ~ '&(quot|#(039|171|187|8222|8220|8221));'
